def median_of_merged_two_sorted(a, b):
    merged = sorted(a + b)
    n = len(merged)
    if n % 2 == 1:
        return float(merged[n // 2])
    return (merged[n // 2 - 1] + merged[n // 2]) / 2

def medians_of_prefixes(nums):
    result = []
    for i in range(len(nums)):
        prefix = sorted(nums[:i + 1])
        n = len(prefix)
        if n % 2 == 1:
            result.append(float(prefix[n // 2]))
        else:
            result.append((prefix[n // 2 - 1] + prefix[n // 2]) / 2)
    return result

def median_of_row_sums(matrix):
    sums = sorted(sum(row) for row in matrix)
    n = len(sums)
    if n % 2 == 1:
        return float(sums[n // 2])
    return (sums[n // 2 - 1] + sums[n // 2]) / 2

def median_absolute_deviation(nums):
    def median(values):
        s = sorted(values)
        n = len(s)
        if n % 2 == 1:
            return float(s[n // 2])
        return (s[n // 2 - 1] + s[n // 2]) / 2
    m = median(nums)
    return median([abs(x - m) for x in nums])

def median_index(nums):
    s = sorted(nums)
    n = len(s)
    if n % 2 == 1:
        med = s[n // 2]
    else:
        med = s[n // 2 - 1]
    return nums.index(med)

def dense_rank(nums):
    distinct_sorted = sorted(set(nums))
    rank_map = {v: i + 1 for i, v in enumerate(distinct_sorted)}
    return [rank_map[x] for x in nums]

def competition_rank(nums):
    s = sorted(nums)
    rank_map = {}
    for i, v in enumerate(s):
        if v not in rank_map:
            rank_map[v] = i + 1
    return [rank_map[x] for x in nums]

def modified_competition_rank(nums):
    s = sorted(nums)
    n = len(s)
    rank_map = {}
    for i in range(n - 1, -1, -1):
        v = s[i]
        if v not in rank_map:
            rank_map[v] = i + 1
    return [rank_map[x] for x in nums]

def ordinal_rank(nums):
    order = sorted(range(len(nums)), key=lambda i: (nums[i], i))
    rank = [0] * len(nums)
    for rank_value, idx in enumerate(order, start=1):
        rank[idx] = rank_value
    return rank

def leaderboard_rank_by_name_tiebreak(entries):
    sorted_entries = sorted(entries, key=lambda e: -e[1])
    rank_map = {}
    for i, (name, score) in enumerate(sorted_entries):
        if score not in rank_map:
            rank_map[score] = i + 1
    return {name: rank_map[score] for name, score in entries}

def leaderboard_top3(entries):
    sorted_entries = sorted(entries, key=lambda e: (-e[1], e[0]))
    return [name for name, score in sorted_entries[:3]]

def leaderboard_position_of_player(entries, name):
    sorted_entries = sorted(entries, key=lambda e: (-e[1], e[0]))
    for i, (n, s) in enumerate(sorted_entries):
        if n == name:
            return i + 1

def leaderboard_with_ranks(entries):
    sorted_entries = sorted(entries, key=lambda e: (-e[1], e[0]))
    result = []
    rank_map = {}
    for i, (name, score) in enumerate(sorted_entries):
        if score not in rank_map:
            rank_map[score] = i + 1
        result.append((rank_map[score], name, score))
    return result
